"""Explicitly labelled KYRO test fixture. Intentionally vulnerable; never deploy."""


import operator
from functools import reduce


allowed_operators = {
    '+': operator.add,
    '-': operator.sub,
    '*': operator.mul,
    '/': operator.truediv,
    '**': operator.pow,
    '(': operator.floordiv,
    ')': operator.floordiv,
}


def calculate(expression: str):
    """Preserve arithmetic behavior while testing remediation of dynamic eval."""
    def eval_node(node):
        if isinstance(node, tuple):
            op, *args = node
            return allowed_operators[op](*map(eval_node, args))
        return node

    return eval_node(eval(expression))
